CREATE TABLE lp_jobs(id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES portfolio_businesses(id), owner TEXT NOT NULL REFERENCES office_users(username), entry_key TEXT NOT NULL, brief TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('mock','openai')), state TEXT NOT NULL, fingerprint TEXT NOT NULL, scope_snapshot TEXT NOT NULL, current_step INTEGER NOT NULL DEFAULT 0, count INTEGER NOT NULL, final_task TEXT NOT NULL REFERENCES tasks(id), final_artifact TEXT REFERENCES artifacts(id), live_approval TEXT, approval_by TEXT, approved_at TEXT, decision_guard INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(business_id,entry_key));
CREATE TABLE lp_steps(job_id TEXT NOT NULL REFERENCES lp_jobs(id), step INTEGER NOT NULL, agent TEXT NOT NULL CHECK(agent IN ('AI01','AI07','AI09')), kind TEXT NOT NULL, state TEXT NOT NULL, output TEXT, output_digest TEXT, PRIMARY KEY(job_id,step));
CREATE TABLE lp_calls(id TEXT PRIMARY KEY, job_id TEXT NOT NULL, step INTEGER NOT NULL, attempt INTEGER NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, request_hash TEXT NOT NULL, state TEXT NOT NULL, input_tokens INTEGER, output_tokens INTEGER, reserved_microusd INTEGER NOT NULL, estimated_microusd INTEGER, input_rate TEXT, output_rate TEXT, price_ref TEXT, error_code TEXT, created_at TEXT NOT NULL, finished_at TEXT, retry_at TEXT, office_cost TEXT REFERENCES office_costs(id), month TEXT NOT NULL, FOREIGN KEY(job_id,step) REFERENCES lp_steps(job_id,step), UNIQUE(job_id,step,attempt));
CREATE TABLE lp_controls(id INTEGER PRIMARY KEY CHECK(id=1), halted INTEGER NOT NULL DEFAULT 0);
INSERT INTO lp_controls VALUES(1,0);
CREATE TABLE lp_audit(id INTEGER PRIMARY KEY, business_id TEXT REFERENCES portfolio_businesses(id), job_id TEXT REFERENCES lp_jobs(id), actor TEXT NOT NULL, event TEXT NOT NULL, created_at TEXT NOT NULL);
